// Mirrors src/blotato/triage.ts. Keep the two classifiers in step.
const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const subject = String(body.subject || '');
const message = String(body.message || body.text || '');
const blob = subject + '\n' + message;
const explicit = String(body.submissionId || body.postSubmissionId || '').trim();
const found = blob.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
const submissionId = explicit || (found ? found[0] : '');
const asksHow = /\b(how do i|how to|where do i|where can i)\b/i.test(blob);
const negated = /\bnothing failed\b|\bdidn't fail\b|\bdid not fail\b/i.test(blob);
const hardTechnical = Boolean(submissionId) || /\b(401|403|422|500|429|timeout|n8n|webhook|error message)\b/i.test(blob);
const publishFailure = !negated && /\b(post failed|failed to publish|failed post|won't publish|did not publish|publishing failed)\b/i.test(blob);
const billing = /\b(refund|invoice|charged|billing|subscription|pricing|receipt|payment)\b/i.test(blob);
let category = 'how-to';
let reason = 'No billing charge and no publish failure.';
if (asksHow && !submissionId && !hardTechnical) {
  category = 'how-to';
  reason = 'The customer is asking how something works.';
} else if (billing && !submissionId && !publishFailure && !hardTechnical) {
  category = 'billing';
  reason = 'The customer is asking about a charge, plan, or invoice.';
} else if (hardTechnical || publishFailure) {
  category = 'technical';
  reason = submissionId ? 'A submission id is present.' : 'The message describes a failed publish.';
} else if (billing) {
  category = 'billing';
  reason = 'Billing words are present without a publish failure.';
}
return [{
  json: {
    customerName: String(body.customerName || ''),
    subject,
    message,
    category,
    reason,
    submissionId
  }
}];

const ticket = $('Classify ticket').first().json;
const api = $input.first().json;
const name = ticket.customerName ? 'Hi ' + ticket.customerName + ',' : 'Hi,';
let detail = 'I have not published or scheduled anything.';
if (ticket.category === 'billing') {
  detail = 'I treated this as a billing question. I have not changed the plan and I have not issued a refund. Open Settings > Billing and check the newest charge. A person on billing confirms refunds.';
} else if (ticket.category === 'how-to') {
  detail = 'Open Accounts in a private window and log into only the network you want to connect. Facebook needs a Page, not a personal profile. To schedule from the API, put scheduledTime next to post and include a timezone. A request with no time publishes immediately.';
} else if (api && api.errorMessage && api.status === 'failed') {
  detail = 'I looked up the submission and the post failed before it went live. The exact error is: ' + api.errorMessage + '. I have not published a replacement. Change the thing that error names before trying again.';
} else if (api && api.status) {
  detail = 'I looked up the submission. The status is ' + api.status + '. I have not published a replacement.';
} else if (api && (api.message || api.error)) {
  detail = 'The Blotato read did not succeed, so I am not going to guess. I have not published a replacement.';
} else if (ticket.category === 'technical') {
  detail = 'This looks like a publish problem. Please send the postSubmissionId from the original create response. The id on a posts-list row is a different id. I have not published a replacement.';
}
return [{
  json: {
    customerName: ticket.customerName,
    category: ticket.category,
    reason: ticket.reason,
    submissionId: ticket.submissionId || null,
    apiSnapshot: api,
    draftReply: name + '\n\n' + detail
  }
}];

const draft = $input.first().json;
return [{
  json: {
    ...draft,
    review: {
      status: 'pending_human_review',
      sendToCustomer: false,
      note: 'A person approves this reply in the helpdesk before anyone sends it. This workflow never calls POST /v2/posts.'
    }
  }
}];
